// Alert when daily total_usage (in USD credits) exceeds a threshold.
// Adjust the threshold in the final WHERE clause to match your budget.
// Default: $50.00 per day.
// MAX→SUM deduplicates re-polled documents for the current day.
FROM metrics-openrouter.usage-*
| WHERE openrouter.usage.total_usage IS NOT NULL
| STATS _v = MAX(openrouter.usage.total_usage) BY @timestamp, openrouter.usage.model, openrouter.usage.api_key_id
| STATS daily_cost_usd = SUM(_v)
| WHERE daily_cost_usd > 50
